import os
from typing import List, Dict, Any

import requests


def detect_text_in_image(image_path: str) -> List[Dict[str, Any]]:
    """
    Detect text appearing inside an image using OCR.Space hosted API.

    Returns a list of detected text items with text and confidence/bounding info when available.
    """
    api_key = os.getenv("OCR_SPACE_API_KEY", "helloworld")
    endpoint = "https://api.ocr.space/parse/image"

    with open(image_path, "rb") as f:
        files = {"filename": f}
        data = {
            "apikey": api_key,
            "language": "eng",
            "isOverlayRequired": "true",
        }
        response = requests.post(endpoint, files=files, data=data, timeout=60)
        response.raise_for_status()
        payload = response.json()

    results: List[Dict[str, Any]] = []
    parsed_results = payload.get("ParsedResults", []) or []
    for parsed in parsed_results:
        text_overlay = parsed.get("TextOverlay", {}) or {}
        lines = text_overlay.get("Lines", []) or []
        for line in lines:
            words = line.get("Words", []) or []
            for word in words:
                results.append(
                    {
                        "text": word.get("WordText", ""),
                        "left": word.get("Left"),
                        "top": word.get("Top"),
                        "height": word.get("Height"),
                        "width": word.get("Width"),
                    }
                )

    if not results:
        # Fallback to extracted full text if overlay details are unavailable
        full_text = ""
        for parsed in parsed_results:
            full_text += (parsed.get("ParsedText") or "") + "\n"
        full_text = full_text.strip()
        if full_text:
            results.append({"text": full_text})

    return results
